"use client";

import { useChat, type UseChatOptions } from "@ai-sdk/react";
import {
  DefaultChatTransport,
  type ChatStatus,
  type ChatTransport,
  type UIMessage,
} from "ai";
import type { HTMLAttributes, ReactNode } from "react";
import type { AgentThinkingVariant } from "@/components/ui/agent-thinking/agent-thinking";
import { cx } from "@/lib/utils";
import { AiComposer } from "@/components/ui/ai-kit/ai-composer";
import { AiConversation } from "@/components/ui/ai-kit/ai-conversation";
import { isChatBusy } from "@/components/ui/ai-kit/message-parts";

export type AiChatProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  /** Prefer a custom transport; otherwise DefaultChatTransport({ api }). */
  transport?: ChatTransport<UIMessage>;
  api?: string;
  /** Forwarded into `useChat` (id, messages, onFinish, …). */
  chatOptions?: UseChatOptions<UIMessage>;
  suggestions?: string[];
  emptyTitle?: ReactNode;
  emptyLabel?: ReactNode;
  placeholder?: string;
  thinkingVariant?: AgentThinkingVariant;
  thinkingLabel?: string;
  composerClassName?: string;
  conversationClassName?: string;
  /**
   * Replace the built-in lightweight composer. Use TipTap Composer here:
   *
   *   import { Composer, ComposerLoader } from "@joyui/react/composer";
   *   renderComposer={({ busy, send, stop }) => (
   *     <ComposerLoader active={busy}>
   *       <Composer busy={busy} onStop={stop} onSubmit={send} />
   *     </ComposerLoader>
   *   )}
   */
  renderComposer?: (ctx: {
    status: ChatStatus;
    busy: boolean;
    send: (text: string) => void;
    stop: () => void;
  }) => ReactNode;
  children?: ReactNode;
};

/**
 * End-to-end JoyUI chat wired to `@ai-sdk/react` `useChat`.
 * `ai` + `@ai-sdk/react` ship with `@joyui/react` — no extra install.
 *
 *   import { AiChat } from "@joyui/react";
 *   <AiChat api="/api/chat" />
 */
export function AiChat({
  transport,
  api = "/api/chat",
  chatOptions,
  suggestions = [
    "解释这段报错",
    "把这段总结成三条要点",
    "帮我起五个产品名",
  ],
  emptyTitle,
  emptyLabel,
  placeholder,
  thinkingVariant,
  thinkingLabel,
  composerClassName,
  conversationClassName,
  renderComposer,
  className,
  children,
  ...props
}: AiChatProps) {
  const hasExternalChat = Boolean(
    chatOptions && "chat" in chatOptions && chatOptions.chat,
  );

  const {
    messages,
    sendMessage,
    status,
    stop,
    error,
    regenerate,
    clearError,
  } = useChat(
    hasExternalChat
      ? chatOptions
      : {
          ...chatOptions,
          transport: transport ?? new DefaultChatTransport({ api }),
        },
  );

  const busy = isChatBusy(status);

  const send = (text: string) => {
    const trimmed = text.trim();
    if (!trimmed || busy) return;
    clearError();
    void sendMessage({ text: trimmed });
  };

  const retry = () => {
    clearError();
    void regenerate();
  };

  return (
    <div
      className={cx(
        "flex h-full min-h-[28rem] w-full flex-col gap-3",
        className,
      )}
      {...props}
    >
      <AiConversation
        className={cx("px-1", conversationClassName)}
        messages={messages}
        status={status}
        error={error}
        suggestions={suggestions}
        emptyTitle={emptyTitle}
        emptyLabel={emptyLabel}
        thinkingVariant={thinkingVariant}
        thinkingLabel={thinkingLabel}
        onSend={send}
        onClearError={clearError}
        onRegenerate={retry}
      />

      <div className={cx("mx-auto w-full max-w-3xl shrink-0", composerClassName)}>
        {renderComposer ? (
          renderComposer({ status, busy, send, stop })
        ) : (
          <AiComposer
            busy={busy}
            placeholder={placeholder}
            onStop={stop}
            onSubmit={send}
          />
        )}
      </div>

      {children}
    </div>
  );
}

"use client";

import {
  RiArrowUpLine,
  RiStopFill,
} from "@remixicon/react";
import {
  useEffect,
  useRef,
  useState,
  type FormEvent,
  type KeyboardEvent,
  type HTMLAttributes,
} from "react";
import { cx } from "@/lib/utils";

/**
 * Lightweight chat input that ships with the AI kit (no TipTap).
 * Swap in `@joyui/react/composer` via `AiChat` `renderComposer` when you want
 * the full pill / panel surface.
 */
export function AiComposer({
  busy = false,
  placeholder = "有什么问题就问我",
  disabled = false,
  onSubmit,
  onStop,
  className,
  ...props
}: {
  busy?: boolean;
  placeholder?: string;
  disabled?: boolean;
  onSubmit: (text: string) => void;
  onStop?: () => void;
} & Omit<HTMLAttributes<HTMLFormElement>, "onSubmit">) {
  const [value, setValue] = useState("");
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const empty = value.trim().length === 0;

  useEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "0px";
    el.style.height = `${Math.min(el.scrollHeight, 144)}px`;
  }, [value]);

  const submit = (event?: FormEvent) => {
    event?.preventDefault();
    if (busy) {
      onStop?.();
      return;
    }
    const text = value.trim();
    if (!text || disabled) return;
    onSubmit(text);
    setValue("");
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      submit();
    }
  };

  return (
    <form
      onSubmit={submit}
      className={cx(
        "bui-composer-shell flex w-full items-end gap-2 rounded-[28px] p-2",
        "bg-background-primary-default transition-[box-shadow] duration-200",
        className,
      )}
      {...props}
    >
      <textarea
        ref={textareaRef}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onKeyDown={onKeyDown}
        placeholder={placeholder}
        rows={1}
        disabled={disabled || busy}
        aria-label="AI 输入"
        className={cx(
          "max-h-36 min-h-[36px] min-w-0 flex-1 resize-none overflow-y-auto bg-transparent px-2 py-2",
          "text-body-regular leading-6 text-text-primary outline-none",
          "placeholder:text-text-tertiary",
          "disabled:cursor-not-allowed disabled:opacity-60",
        )}
      />
      <button
        type="submit"
        aria-label={busy ? "停止生成" : "发送"}
        disabled={!busy && (empty || disabled)}
        className={cx(
          "mb-0.5 flex size-9 shrink-0 items-center justify-center rounded-full",
          "transition-[background-color,color,transform,opacity] duration-150",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
          busy
            ? "cursor-pointer bg-button-primary text-white shadow-xs hover:opacity-90 active:scale-95"
            : empty || disabled
              ? "cursor-not-allowed bg-background-tertiary-default text-foreground-icon-quaternary"
              : "cursor-pointer bg-button-primary text-white shadow-xs hover:opacity-90 active:scale-95",
        )}
      >
        {busy ? (
          <RiStopFill className="size-4" aria-hidden />
        ) : (
          <RiArrowUpLine className="size-5" aria-hidden />
        )}
      </button>
    </form>
  );
}

"use client";

import { useEffect, useRef, type HTMLAttributes, type ReactNode } from "react";
import type { ChatStatus, UIMessage } from "ai";
import { PromptSuggestions } from "@/components/ui/prompt-suggestions/prompt-suggestions";
import {
  AgentThinking,
  type AgentThinkingVariant,
} from "@/components/ui/agent-thinking/agent-thinking";
import { cx } from "@/lib/utils";
import { AiMessage } from "@/components/ui/ai-kit/ai-message";
import { isChatBusy, shouldShowThinking } from "@/components/ui/ai-kit/message-parts";

export interface AiConversationProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  messages: UIMessage[];
  status?: ChatStatus;
  error?: Error | null;
  /** Empty-state chips; selecting one calls `onSend`. */
  suggestions?: string[];
  emptyLabel?: ReactNode;
  emptyTitle?: ReactNode;
  onSend?: (text: string) => void;
  onRegenerate?: () => void;
  onClearError?: () => void;
  thinkingVariant?: AgentThinkingVariant;
  thinkingLabel?: string;
  /** Auto-scroll to bottom when messages / status change. Default true. */
  autoScroll?: boolean;
  children?: ReactNode;
}

/**
 * Transcript surface for `@ai-sdk/react` `useChat` — maps `UIMessage[]` to
 * JoyUI `AiMessage`, shows thinking while waiting for text, and an empty state.
 */
export function AiConversation({
  messages,
  status = "ready",
  error,
  suggestions,
  emptyLabel = "试着问我",
  emptyTitle = "今天想聊点什么？",
  onSend,
  onRegenerate,
  onClearError,
  thinkingVariant = "wave",
  thinkingLabel = "Thinking",
  autoScroll = true,
  className,
  children,
  ...props
}: AiConversationProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const busy = isChatBusy(status);
  const showThinking = shouldShowThinking(messages, status);

  useEffect(() => {
    if (!autoScroll) return;
    const node = scrollRef.current;
    if (!node) return;
    node.scrollTo({ top: node.scrollHeight, behavior: "smooth" });
  }, [messages, status, autoScroll, showThinking]);

  return (
    <div
      ref={scrollRef}
      className={cx(
        "flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto scroll-smooth",
        className,
      )}
      {...props}
    >
      {messages.length === 0 ? (
        <div className="flex min-h-[12rem] flex-1 flex-col items-center justify-center gap-4 px-2 text-center">
          <div className="flex flex-col gap-1">
            <h2 className="text-title-2-medium text-text-primary">{emptyTitle}</h2>
            {typeof emptyLabel === "string" ? (
              <p className="text-body-regular text-text-secondary">{emptyLabel}</p>
            ) : (
              emptyLabel
            )}
          </div>
          {suggestions && suggestions.length > 0 && onSend ? (
            <PromptSuggestions
              className="items-center"
              suggestions={suggestions}
              onSelect={onSend}
            />
          ) : null}
        </div>
      ) : (
        messages.map((message, index) => (
          <AiMessage
            key={message.id}
            message={message}
            streaming={
              busy &&
              index === messages.length - 1 &&
              message.role === "assistant"
            }
            onRegenerate={
              index === messages.length - 1 && message.role === "assistant"
                ? onRegenerate
                : undefined
            }
          />
        ))
      )}

      {showThinking ? (
        <AgentThinking
          variant={thinkingVariant}
          label={thinkingLabel}
          className="px-1"
        />
      ) : null}

      {error ? (
        <div
          role="alert"
          className="flex flex-wrap items-center gap-2 rounded-xl border border-separator-border bg-background-secondary-default px-3 py-2"
        >
          <p className="min-w-0 flex-1 text-body-regular text-text-secondary">
            {error.message || "请求失败，请稍后重试。"}
          </p>
          <div className="flex shrink-0 items-center gap-1">
            {onClearError ? (
              <button
                type="button"
                onClick={onClearError}
                className="rounded-lg px-2 py-1 text-caption-1-medium text-text-tertiary transition-colors hover:bg-background-secondary-hover hover:text-text-primary"
              >
                关闭
              </button>
            ) : null}
            {onRegenerate ? (
              <button
                type="button"
                onClick={onRegenerate}
                className="rounded-lg bg-background-primary-default px-2.5 py-1 text-caption-1-medium text-text-primary shadow-xs transition-colors hover:bg-background-secondary-hover"
              >
                重试
              </button>
            ) : null}
          </div>
        </div>
      ) : null}

      {children}
    </div>
  );
}

"use client";

import {
  RiFileCopyLine,
  RiRefreshLine,
} from "@remixicon/react";
import { useEffect, useState, type HTMLAttributes, type ReactNode } from "react";
import type { UIMessage } from "ai";
import { Citation } from "@/components/ui/citation/citation";
import { MessageActions } from "@/components/ui/message-actions/message-actions";
import { ChatMessage } from "@/components/ui/chat-message/chat-message";
import { ReasoningBlock } from "@/components/ui/reasoning-block/reasoning-block";
import { ToolCall } from "@/components/ui/tool-call/tool-call";
import { cx } from "@/lib/utils";
import {
  formatToolOutput,
  getToolName,
  getUIMessageSources,
  getUIMessageText,
  isReasoningUIPart,
  isToolUIPart,
  mapToolStateToStatus,
  summarizeToolInput,
} from "@/components/ui/ai-kit/message-parts";

export interface AiMessageProps
  extends Omit<HTMLAttributes<HTMLElement>, "children" | "role"> {
  message: UIMessage;
  /** Last assistant turn still receiving tokens. */
  streaming?: boolean;
  onRegenerate?: () => void;
  /** Extra content after built-in parts (custom data parts, etc.). */
  children?: ReactNode;
}

/**
 * Renders one AI SDK `UIMessage` with JoyUI transcript primitives:
 * ChatMessage + ReasoningBlock + ToolCall + Citation + MessageActions.
 */
export function AiMessage({
  message,
  streaming = false,
  onRegenerate,
  className,
  children,
  ...props
}: AiMessageProps) {
  const text = getUIMessageText(message);
  const sources = getUIMessageSources(message);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 1600);
    return () => clearTimeout(timer);
  }, [copied]);

  const fileParts = message.parts.filter((part) => part.type === "file");

  if (message.role === "user") {
    if (!text && fileParts.length === 0) return null;
    return (
      <ChatMessage role="user" className={className} {...props}>
        {fileParts.map((part, index) => (
          <FilePartView key={`file-${index}`} part={part} />
        ))}
        {text}
      </ChatMessage>
    );
  }

  if (message.role === "system") {
    if (!text) return null;
    return (
      <ChatMessage role="system" className={className} {...props}>
        {text}
      </ChatMessage>
    );
  }

  const hasBody =
    message.parts.some(
      (part) =>
        part.type === "text" ||
        part.type === "file" ||
        isReasoningUIPart(part) ||
        isToolUIPart(part) ||
        part.type === "source-url" ||
        part.type === "source-document",
    ) || Boolean(children);

  if (!hasBody && !streaming) return null;

  return (
    <ChatMessage
      role="assistant"
      streaming={streaming && text.length === 0}
      className={cx("gap-2.5", className)}
      {...props}
    >
      {message.parts.map((part, index) => {
        if (isReasoningUIPart(part)) {
          const streamingReason = part.state === "streaming";
          return (
            <ReasoningBlock
              key={part.id ?? `reasoning-${index}`}
              status={streamingReason ? "streaming" : "done"}
              defaultOpen={streamingReason}
              title={streamingReason ? undefined : "Thought"}
            >
              {part.text}
            </ReasoningBlock>
          );
        }

        if (isToolUIPart(part)) {
          const name = getToolName(part);
          const status = mapToolStateToStatus(part.state);
          const error =
            part.state === "output-error" ? part.errorText : undefined;
          const body =
            part.state === "output-available"
              ? formatToolOutput(part.output)
              : part.state === "input-streaming" ||
                  part.state === "input-available" ||
                  part.state === "approval-requested" ||
                  part.state === "approval-responded"
                ? formatToolOutput(part.input)
                : undefined;

          return (
            <ToolCall
              key={part.toolCallId}
              name={name}
              status={status}
              summary={summarizeToolInput(
                "input" in part ? part.input : undefined,
              )}
              error={error}
              defaultOpen={status === "error" || status === "running"}
            >
              {body}
            </ToolCall>
          );
        }

        if (part.type === "file") {
          return <FilePartView key={`file-${index}`} part={part} />;
        }

        if (part.type === "text" && part.text) {
          const lastText =
            message.parts.map((p, i) => (p.type === "text" ? i : -1)).filter((i) => i >= 0).at(-1) ===
            index;
          return (
            <p
              key={`text-${index}`}
              className="text-body-regular whitespace-pre-wrap break-words text-text-primary"
            >
              {part.text}
              {streaming && lastText ? (
                <span
                  aria-hidden
                  className="bui-typing-caret ms-0.5 inline-block h-[1em] w-[2px] translate-y-[0.1em] bg-accent-500 align-baseline"
                />
              ) : null}
            </p>
          );
        }

        return null;
      })}

      {sources.length > 0 ? (
        <div className="flex flex-wrap gap-1.5">
          {sources.map((source, index) => (
            <Citation
              key={source.id}
              index={index + 1}
              title={source.title}
              href={source.href}
            />
          ))}
        </div>
      ) : null}

      {children}

      {text || onRegenerate ? (
        <MessageActions
          hidden={streaming}
          actions={[
            ...(text
              ? [
                  {
                    id: "copy",
                    label: copied ? "已复制" : "复制",
                    icon: RiFileCopyLine,
                    onPress: async () => {
                      try {
                        await navigator.clipboard.writeText(text);
                        setCopied(true);
                      } catch {
                        // Clipboard may be blocked.
                      }
                    },
                  },
                ]
              : []),
            ...(onRegenerate
              ? [
                  {
                    id: "regen",
                    label: "重新生成",
                    icon: RiRefreshLine,
                    onPress: onRegenerate,
                    disabled: streaming,
                  },
                ]
              : []),
          ]}
        />
      ) : null}
    </ChatMessage>
  );
}

function FilePartView({
  part,
}: {
  part: { type: "file"; mediaType: string; url: string; filename?: string };
}) {
  const isImage =
    part.mediaType === "image" || part.mediaType.startsWith("image/");

  if (isImage) {
    return (
      <img
        src={part.url}
        alt={part.filename ?? "attachment"}
        className="max-h-56 max-w-full rounded-xl border border-separator-border object-contain"
      />
    );
  }

  return (
    <a
      href={part.url}
      target="_blank"
      rel="noreferrer"
      className="inline-flex max-w-full items-center gap-1.5 rounded-lg border border-separator-border bg-background-secondary-default px-2.5 py-1.5 text-caption-1-medium text-text-secondary transition-colors hover:bg-background-secondary-hover hover:text-text-primary"
    >
      <span className="truncate">{part.filename ?? part.mediaType}</span>
    </a>
  );
}

/**
 * First-party re-exports so apps can stay on `@joyui/react` / `@joyui/react/ai`
 * without a separate install of the AI SDK packages (they ship as dependencies).
 */
export { useChat } from "@ai-sdk/react";
export type { UseChatHelpers, UseChatOptions } from "@ai-sdk/react";
export { DefaultChatTransport } from "ai";
export type {
  ChatStatus,
  ChatTransport,
  UIMessage,
  UIMessagePart,
} from "ai";

import {
  getToolName,
  isReasoningUIPart,
  isToolUIPart,
  type ChatStatus,
  type UIMessage,
} from "ai";
import type { ToolCallStatus } from "@/components/ui/tool-call/tool-call";

/** True while a reply is queued or streaming. */
export function isChatBusy(status: ChatStatus): boolean {
  return status === "submitted" || status === "streaming";
}

/** Join all text parts on a UIMessage. */
export function getUIMessageText(message: UIMessage): string {
  return message.parts
    .filter((part): part is { type: "text"; text: string } => part.type === "text")
    .map((part) => part.text)
    .join("");
}

/** Show AgentThinking until the latest assistant turn has visible text. */
export function shouldShowThinking(
  messages: UIMessage[],
  status: ChatStatus,
): boolean {
  if (!isChatBusy(status)) return false;
  const last = messages[messages.length - 1];
  if (!last || last.role !== "assistant") return true;
  return getUIMessageText(last).length === 0;
}

export function mapToolStateToStatus(
  state: string | undefined,
): ToolCallStatus {
  if (state === "output-error") return "error";
  if (
    state === "output-available" ||
    state === "output-denied" ||
    state === "approval-responded"
  ) {
    return "done";
  }
  if (
    state === "input-streaming" ||
    state === "input-available" ||
    state === "approval-requested"
  ) {
    return "running";
  }
  return "pending";
}

export function summarizeToolInput(input: unknown): string | undefined {
  if (input == null) return undefined;
  if (typeof input === "string") {
    return input.length > 96 ? `${input.slice(0, 93)}…` : input;
  }
  try {
    const raw = JSON.stringify(input);
    if (!raw || raw === "{}") return undefined;
    return raw.length > 96 ? `${raw.slice(0, 93)}…` : raw;
  } catch {
    return undefined;
  }
}

export function formatToolOutput(output: unknown): string | undefined {
  if (output == null) return undefined;
  if (typeof output === "string") return output;
  try {
    return JSON.stringify(output, null, 2);
  } catch {
    return String(output);
  }
}

export type AiSource = {
  id: string;
  title: string;
  href?: string;
};

/** Collect source-url / source-document parts for Citation rows. */
export function getUIMessageSources(message: UIMessage): AiSource[] {
  const sources: AiSource[] = [];
  for (const part of message.parts) {
    if (part.type === "source-url") {
      sources.push({
        id: part.sourceId,
        title: part.title ?? part.url,
        href: part.url,
      });
    } else if (part.type === "source-document") {
      sources.push({
        id: part.sourceId,
        title: part.title,
      });
    }
  }
  return sources;
}

export {
  getToolName,
  isReasoningUIPart,
  isToolUIPart,
};
